// Plugin host: the DAW side of the plugin ABI (third_party/daw_plugin_abi). Instances are created
// and destroyed on the control thread; the audio thread only calls process() through Engine.
#pragma once

#include <stdint.h>

#include <atomic>
#include <memory>
#include <string>
#include <vector>

#include "daw/audio_file.hpp"
#include "daw/model.hpp"
#include "daw_plugin_api.h"

struct cJSON;

namespace daw {

// the plugins linked into this build (generated by scripts/import-plugins.sh into
// plugins/generated/daw_plugin_registry.c, or a test registry)
struct PluginRegistry {
    static const std::vector<const daw_plugin_descriptor_t *> &all();
    static const daw_plugin_descriptor_t *find(const std::string &id);
    // the DAW's ABI check, applied to every registry entry at start-up
    static bool compatible(const daw_plugin_descriptor_t *d);
};

class PluginInstance {
public:
    // nullptr if the plugin refuses (memory) or is incompatible; `err` says why
    static PluginInstance *create(const daw_plugin_descriptor_t *d, uint32_t sampleRate, uint32_t maxBlock,
                                  std::string *err = nullptr);
    static void destroy(PluginInstance *p);
    using ParallelService = int32_t (*)(void *, void (*)(void *), void *, void (*)(void *), void *);
    // Registered once before the audio task starts. Null service retains serial plugin DSP.
    static void setParallelService(ParallelService service, void *context = nullptr);
    std::atomic<uint32_t> parallelJobs{0}, parallelDeclined{0};
    bool activate() { return desc_->activate(inst_) == DAW_OK; }  // after applyState, before the engine

    const daw_plugin_descriptor_t *desc() const { return desc_; }
    daw_plugin_instance_t *handle() const { return inst_; }

    // parameters by stable key (project files) or id; values are plain and clamped
    int paramIndex(const std::string &key) const;
    bool setParam(const std::string &key, float v, uint32_t *idOut = nullptr, float *clamped = nullptr);
    void setParamById(uint32_t id, float v);  // control thread, only while not installed in the engine
    float paramValue(uint32_t index) const { return values_[index]; }
    void noteParam(uint32_t index, float v) { values_[index] = v; }  // the engine got it as an event
    float clampParam(uint32_t index, float v) const;
    bool presetValues(const std::string &name, std::vector<float> &out) const;

    // apply a project's saved state (params, preset, blob) before activation; unknown keys ignored
    void applyState(const PluginState &st);
    // ABI 1.1: before activate(). The instance keeps the resource alive until it is destroyed.
    int resourceSlot(const std::string &key) const;  // -1: no such slot
    bool setResource(int slot, std::shared_ptr<const LoadedResource> res);
    void captureState(PluginState &st) const;
    // Control-thread inspection of the immutable resource actually bound to this instance.
    const LoadedResource *retainedResource(const std::string &name) const;

    // accounting (written by the host services and the audio thread)
    size_t memFast() const { return memFast_.load(); }
    size_t memLarge() const { return memLarge_.load(); }
    std::atomic<uint32_t> cycles{0};      // accumulated by the audio thread
    std::atomic<uint32_t> calls{0};
    std::atomic<uint32_t> cpuPermille{0}; // published once per second by the engine
    std::atomic<uint32_t> voices{0};
    std::atomic<uint32_t> reports{0};
    std::atomic<int32_t> lastReport{0};

private:
    PluginInstance() = default;
    static void *hostAlloc(void *ctx, size_t size, size_t align, uint32_t flags);
    static void hostFree(void *ctx, void *p);
    static void hostLog(void *ctx, int level, const char *msg);
    static void hostReport(void *ctx, int32_t code);
    static int32_t hostParallel(void *ctx, void (*local)(void *), void *localArg,
                                void (*remote)(void *), void *remoteArg);

    const daw_plugin_descriptor_t *desc_ = nullptr;
    daw_plugin_instance_t *inst_ = nullptr;
    daw_host_api_t api_{};
    std::vector<float> values_;
    std::atomic<size_t> memFast_{0}, memLarge_{0};
    std::vector<std::shared_ptr<const LoadedResource>> keep_;
};

// browser catalog: every plugin's descriptor as JSON (parameters, presets, capabilities)
cJSON *pluginCatalogJson();
cJSON *pluginDescriptorJson(const daw_plugin_descriptor_t *d);

}  // namespace daw
